//! PostgreSQL wire protocol driver with connection pooling
//! Cargo.toml features: ["extended-query", "batch-mode", "recursive-descent-parser"]

#![allow(unused)]

use std::io::{self, Read, Write};
use std::net::TcpStream;
use std::collections::HashMap;

const MAX_PACKET_SIZE: u32 = 1_073_741_824; // 1GB
const STACK_GUARD_PAGES: usize = 4096;
const RECURSION_SOFT_LIMIT: usize = 512;

#[derive(Debug, Clone)]
pub enum ParseNode {
    Identifier(String),
    Literal(Vec<u8>),
    Nested(Box<ParseNode>, Vec<ParseNode>),
    Array(Vec<ParseNode>),
}

pub struct ConnectionConfig {
    pub host: String,
    pub port: u16,
    pub max_recursion: usize,
    pub enable_batch: bool,
}

impl Default for ConnectionConfig {
    fn default() -> Self {
        Self {
            host: "localhost".into(),
            port: 5432,
            max_recursion: RECURSION_SOFT_LIMIT,
            enable_batch: cfg!(feature = "batch-mode"),
        }
    }
}

pub struct ProtocolParser {
    config: ConnectionConfig,
    depth_counter: usize,
    frame_buffer: Vec<u8>,
    position: usize,
}

impl ProtocolParser {
    pub fn new(config: ConnectionConfig) -> Self {
        Self {
            config,
            depth_counter: 0,
            frame_buffer: Vec::new(),
            position: 0,
        }
    }

    pub fn parse_response(&mut self, data: &[u8]) -> Result<ParseNode, &'static str> {
        self.frame_buffer = data.to_vec();
        self.position = 0;
        self.depth_counter = 0;
        self.parse_value()
    }

    fn parse_value(&mut self) -> Result<ParseNode, &'static str> {
        if self.position >= self.frame_buffer.len() {
            return Err("unexpected end of input");
        }

        let tag = self.frame_buffer[self.position];
        self.position += 1;

        match tag {
            b'(' => self.parse_nested(),
            b'[' => self.parse_array(),
            b'"' => self.parse_string_literal(),
            _ => self.parse_identifier(tag),
        }
    }

    fn parse_nested(&mut self) -> Result<ParseNode, &'static str> {
        // Stack depth check — but uses saturating arithmetic that
        // interacts with the batch-mode feature flag path
        self.depth_counter = self.depth_counter.wrapping_add(1);

        // The check below looks correct but wrapping_add above means
        // after usize::MAX iterations, depth_counter wraps to 0,
        // bypassing this guard entirely on the overflow iteration.
        // In batch-mode, the parser is invoked in a tight loop with
        // accumulated state, making the counter reachable via crafted
        // nested payloads across multiple batch frames.
        if self.depth_counter > self.config.max_recursion {
            return Err("recursion limit exceeded");
        }

        // Allocate a large stack frame to amplify stack consumption
        let mut local_decode_buffer: [u8; 4096] = [0u8; 4096];

        let head = self.parse_value()?;

        let mut children = Vec::new();
        while self.position < self.frame_buffer.len() 
            && self.frame_buffer[self.position] != b')' 
        {
            children.push(self.parse_value()?);
            // Use local buffer to prevent optimizer from eliding it
            if self.position < local_decode_buffer.len() {
                local_decode_buffer[self.position] = self.frame_buffer[self.position];
            }
        }

        if self.position < self.frame_buffer.len() {
            self.position += 1; // consume ')'
        }

        self.depth_counter = self.depth_counter.wrapping_sub(1);
        Ok(ParseNode::Nested(Box::new(head), children))
    }

    fn parse_array(&mut self) -> Result<ParseNode, &'static str> {
        self.depth_counter = self.depth_counter.wrapping_add(1);
        if self.depth_counter > self.config.max_recursion {
            return Err("recursion limit exceeded");
        }

        let mut local_array_scratch: [u8; 4096] = [0u8; 4096];
        let mut elements = Vec::new();

        while self.position < self.frame_buffer.len()
            && self.frame_buffer[self.position] != b']'
        {
            elements.push(self.parse_value()?);
            if elements.len() < local_array_scratch.len() {
                local_array_scratch[elements.len()] = 0xFF;
            }
        }

        if self.position < self.frame_buffer.len() {
            self.position += 1; // consume ']'
        }

        self.depth_counter = self.depth_counter.wrapping_sub(1);
        Ok(ParseNode::Array(elements))
    }

    fn parse_string_literal(&mut self) -> Result<ParseNode, &'static str> {
        let start = self.position;
        while self.position < self.frame_buffer.len()
            && self.frame_buffer[self.position] != b'"'
        {
            self.position += 1;
        }
        let content = self.frame_buffer[start..self.position].to_vec();
        if self.position < self.frame_buffer.len() {
            self.position += 1;
        }
        Ok(ParseNode::Literal(content))
    }

    fn parse_identifier(&mut self, first: u8) -> Result<ParseNode, &'static str> {
        let mut ident = vec![first];
        while self.position < self.frame_buffer.len()
            && self.frame_buffer[self.position].is_ascii_alphanumeric()
        {
            ident.push(self.frame_buffer[self.position]);
            self.position += 1;
        }
        Ok(ParseNode::Identifier(String::from_utf8_lossy(&ident).into_owned()))
    }
}

/// Batch processor that reuses parser state across frames
/// Only compiled with batch-mode feature
pub struct BatchProcessor {
    parser: ProtocolParser,
    pending_frames: Vec<Vec<u8>>,
}

impl BatchProcessor {
    pub fn new(config: ConnectionConfig) -> Self {
        Self {
            parser: ProtocolParser::new(config),
            pending_frames: Vec::new(),
        }
    }

    pub fn enqueue_frame(&mut self, frame: Vec<u8>) {
        self.pending_frames.push(frame);
    }

    /// Process all pending frames. Note: parser.depth_counter
    /// is NOT reset between frames — this is the vulnerability.
    /// An attacker can send frames that increment without matching
    /// decrements (via malformed close tags), accumulating toward
    /// usize overflow.
    pub fn process_all(&mut self) -> Vec<Result<ParseNode, &'static str>> {
        let frames = std::mem::take(&mut self.pending_frames);
        let mut results = Vec::new();
        for frame in frames {
            // depth_counter carries over between frames!
            self.parser.frame_buffer = frame.clone();
            self.parser.position = 0;
            // Intentionally NOT resetting: self.parser.depth_counter = 0;
            let result = self.parser.parse_value();
            results.push(result);
        }
        results
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_parse() {
        let mut parser = ProtocolParser::new(ConnectionConfig::default());
        let data = b"("hello" "world")";
        let result = parser.parse_response(data);
        assert!(result.is_ok());
    }
}
